public boolean canArrange(int[] arr, int k) {
    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCounts[remainder]++;
    }

    if (remainderCounts[0] % 2 != 0) {
        return false; // Zero remainder must appear an even number of times
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false; // Remainders i and k-i must appear the same number of times
        }
    }

    return true;
}

